async () => {
  const get = async id => (await cloudflare.request({ method: "GET", path: `/accounts/${accountId}/workflows/extraction/instances/${id}` })).result.output.units;
  const a = await get("itm_3b033a2f"), b = await get("itm_0cb144c0");
  const norm = s => s.replace(/[’‘]/g,"'").replace(/[“”]/g,'"');
  const diffs = [];
  for (let i = 0; i < Math.max(a.length,b.length); i++) {
    if (norm(a[i]?.display ?? "") !== norm(b[i]?.display ?? "")) diffs.push({ i, sock: a[i]?.display?.slice(0,400), copy: b[i]?.display?.slice(0,400), sockKeys: Object.keys(a[i]||{}), copyKeys: Object.keys(b[i]||{}) });
